  for (const k of [7, 1, 0]) { const a = V[k], b = V[(k + 1) % 8], f = (u, zz) => P.I(lerp(a[0], b[0], u), lerp(a[1], b[1], u), z + zz); P.shape([f(0, 0), f(1, 0), f(1, h), f(0, h)], tones[k], 1.1); if (deco) deco(f, k, tones[k]); }
